<div id="deliverableModal" class="fixed inset-0 z-50 items-center justify-center p-4 bg-primary/80 backdrop-blur-sm transition-all duration-300 hidden" onclick="closeDeliverableModal(event)"><div class="relative bg-surface-container-lowest rounded-xl max-w-3xl w-full overflow-hidden shadow-2xl border border-outline-variant/30 flex flex-col" onclick="event.stopPropagation()"><div class="relative w-full bg-surface-container-low max-h-[60vh] flex items-center justify-center overflow-hidden"><img id="modalImage" src="https://lh3.googleusercontent.com/aida/AEtjO1XkYKGLKTNRj2Iv1tXOjYIfBhgMw99DkFEOBL-DTQv3eUEHBTCijOcEID0tkQuPGgeuS0YNBcaRZSu3jjyrhMoB7aJEd3E7w2uULEugY0L6mLJbledWGomVS1Met_p-2FRC54CfSMIyql1_ElXavEikDObqBIPZ23MrWV2sYwG4oHePp7O9o3lS-SeluaCgE_Etp9AahPt_8Y_yE0XuOOVW4adYbTreyecZryT4OQmnf3gfnN99z5oMPA" alt="Dual-Robot Welding Cell" class="w-full h-auto max-h-[60vh] object-contain rounded-t-xl"><button onclick="hideDeliverableModal()" aria-label="Tutup Modal" class="absolute top-3 right-3 w-9 h-9 rounded-full bg-surface-container-lowest/90 hover:bg-surface-container-highest text-primary shadow-md flex items-center justify-center transition-colors z-10 backdrop-blur-sm"><span class="material-symbols-outlined text-[20px]">close</span></button></div><div class="p-space-lg flex flex-col"><h3 id="modalTitle" class="font-headline-sm text-headline-sm text-primary tracking-tight font-bold mb-2">Dual-Robot Welding Cell</h3><p id="modalDesc" class="font-body-md text-body-md text-on-surface-variant leading-relaxed"></p></div></div></div>

<script>
  function openDeliverableModal(imgSrc, title, subtitle) {
    const modal = document.getElementById('deliverableModal');
    const modalImg = document.getElementById('modalImage');
    const modalTitle = document.getElementById('modalTitle');
    const modalSubtitle = document.getElementById('modalSubtitle');
    if (modal && modalImg && modalTitle) {
      modalImg.src = imgSrc;
      modalImg.alt = title;
      modalTitle.textContent = title;
      if (modalSubtitle) modalSubtitle.textContent = subtitle || '';
      modal.classList.remove('hidden');
      modal.classList.add('flex');
      document.body.style.overflow = 'hidden';
    }
  }

  function hideDeliverableModal() {
    const modal = document.getElementById('deliverableModal');
    if (modal) {
      modal.classList.add('hidden');
      modal.classList.remove('flex');
      document.body.style.overflow = '';
    }
  }

  function closeDeliverableModal(event) {
    if (event.target.id === 'deliverableModal') {
      hideDeliverableModal();
    }
  }

  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      hideDeliverableModal();
    }
  });
</script>






